$(document).on("WebPlayerSeIniciaSistema",function(){var control=Ciel.MPC.WebPlayer.Utilidad.ObtenerControl("PasoDos","Horas");if(!control||!control.DivContenedor){return;}
var divContenedor=control.DivContenedor[0];if(!divContenedor){return;}
var select=divContenedor.querySelector('select');if(!select){return;}
select.addEventListener('change',function(evento){if(this.selectedIndex&&this.selectedIndex!=0){return;}
PasoDos.visibilidadSeleccionHora();});});